                dut.write_ptr,
                read_ptr_before,
                dut.read_ptr,
                full,
                empty
            );

        end

    endtask


    // ========================================================
    // CHECK BIT
    // ========================================================

    task check_bit;

        input [8*80-1:0] check_name;
        input actual;
        input expected;

        begin

            total_checks = total_checks + 1;

            if (actual === expected) begin

                passed_checks = passed_checks + 1;

            end
            else begin

                failed_checks = failed_checks + 1;

                $display(
                    "CHECK_FAIL : %0s actual=%b expected=%b",
                    check_name,
                    actual,
                    expected
                );

            end

        end

    endtask


    // ========================================================
    // CHECK COUNT
    // ========================================================

    task check_count;

        input [8*80-1:0] check_name;
        input [2:0] actual;
        input integer expected;

        begin

            total_checks = total_checks + 1;

            if (actual === expected[2:0]) begin

                passed_checks = passed_checks + 1;

            end
            else begin

                failed_checks = failed_checks + 1;

                $display(
                    "CHECK_FAIL : %0s actual=%0d expected=%0d",
                    check_name,
                    actual,
                    expected
                );

            end

        end

    endtask


    // ========================================================
    // CHECK READ DATA
    // ========================================================

    task check_data;

        input [7:0] actual;
        input [7:0] expected;

        begin

            total_checks = total_checks + 1;

            if (actual === expected) begin

                passed_checks = passed_checks + 1;

            end
            else begin

                failed_checks = failed_checks + 1;

                $display(
                    "CHECK_FAIL : RANDOM READ transaction=%0d actual=%02h expected=%02h",
                    transaction_number,
                    actual,
                    expected
                );

            end

        end

    endtask


    // ========================================================
    // RESET
    // ========================================================

    task reset_fifo;

        begin

            @(negedge clk);

            count_before = dut.count;
            write_ptr_before = dut.write_ptr;
            read_ptr_before = dut.read_ptr;

            rst = 1'b1;
            wr_en = 1'b0;
            rd_en = 1'b0;
            data_in = 8'h00;

            @(posedge clk);

            #1;

            model_count = 0;
            model_write_ptr = 0;
            model_read_ptr = 0;

            model_mem[0] = 8'h00;
            model_mem[1] = 8'h00;
            model_mem[2] = 8'h00;
            model_mem[3] = 8'h00;

            log_cycle(
                1'b1,
                1'b0,
                1'b0
            );

            check_count(
                "COUNT AFTER RESET",
                dut.count,
                0
            );

            check_bit(
                "FULL AFTER RESET",
                full,
                1'b0
            );

            check_bit(
                "EMPTY AFTER RESET",
                empty,
                1'b1
            );

            // Release reset safely before next active edge.
            rst = 1'b0;

        end

    endtask


    // ========================================================
