    // ========================================================

    task apply_transaction;

        input write_value;
        input read_value;
        input [7:0] input_value;

        begin

            transaction_number =
                transaction_number + 1;


            // ------------------------------------------------
            // Apply all random stimulus only at negedge.
            // ------------------------------------------------

            @(negedge clk);

            rst = 1'b0;

            wr_en = write_value;
            rd_en = read_value;
            data_in = input_value;


            // ------------------------------------------------
            // Save DUT state BEFORE operation.
            // ------------------------------------------------

            count_before = dut.count;

            write_ptr_before =
                dut.write_ptr;

            read_ptr_before =
                dut.read_ptr;


            // ------------------------------------------------
            // Determine legal write using PRE-CLOCK model.
            // ------------------------------------------------

            if (
                (write_value === 1'b1)
                &&
                (model_count < 4)
            ) begin

                write_allowed = 1'b1;

            end
            else begin

                write_allowed = 1'b0;

            end


            // ------------------------------------------------
            // Determine legal read using PRE-CLOCK model.
            // ------------------------------------------------

            if (
                (read_value === 1'b1)
                &&
                (model_count > 0)
            ) begin

                read_allowed = 1'b1;

                expected_read_data =
                    model_mem[
                        model_read_ptr
                    ];

            end
            else begin

                read_allowed = 1'b0;

                expected_read_data =
                    8'h00;

            end


            // ------------------------------------------------
            // DUT samples transaction.
            // ------------------------------------------------

            @(posedge clk);

            #1;


            // ------------------------------------------------
            // Validate read result.
            // ------------------------------------------------

            if (read_allowed) begin

                check_data(
                    data_out,
                    expected_read_data
                );

            end


            // ------------------------------------------------
            // Update reference-model write.
            // ------------------------------------------------

            if (write_allowed) begin

                model_mem[
                    model_write_ptr
                ] = input_value;

                if (
                    model_write_ptr == 3
                ) begin

                    model_write_ptr = 0;

                end
                else begin

                    model_write_ptr =
                        model_write_ptr + 1;

                end

            end


            // ------------------------------------------------
            // Update reference-model read pointer.
            // ------------------------------------------------

            if (read_allowed) begin

                if (
                    model_read_ptr == 3
                ) begin

                    model_read_ptr = 0;

                end
                else begin

                    model_read_ptr =
                        model_read_ptr + 1;

                end

            end


            // ------------------------------------------------
            // Update reference-model count.
            // ------------------------------------------------

            if (
                write_allowed
                &&
                !read_allowed
            ) begin

                model_count =
                    model_count + 1;

            end
            else if (
                !write_allowed
                &&
                read_allowed
            ) begin

                model_count =
                    model_count - 1;

            end


            // ------------------------------------------------
            // Expected status flags.
            // ------------------------------------------------

            if (model_count == 4) begin
                expected_full = 1'b1;
            end
            else begin
                expected_full = 1'b0;
            end

            if (model_count == 0) begin
                expected_empty = 1'b1;
            end
            else begin
                expected_empty = 1'b0;
            end


            // ------------------------------------------------
            // Verify state.
            // ------------------------------------------------

            check_count(
                "RANDOM FIFO COUNT",
                dut.count,
                model_count
            );

            check_bit(
                "RANDOM FIFO FULL",
                full,
                expected_full
            );

            check_bit(
                "RANDOM FIFO EMPTY",
                empty,
                expected_empty
            );


            // ------------------------------------------------
            // Trace executed transaction.
            // ------------------------------------------------

            log_cycle(
                1'b0,
                write_value,
                read_value
            );


            // ------------------------------------------------
            // Console evidence.
            // ------------------------------------------------

            $display(
                "RANDOM_TRANSACTION=%0d wr=%0d rd=%0d data=%02h count=%0d full=%0d empty=%0d",
                transaction_number,
                write_value,
                read_value,
                input_value,
                dut.count,
                full,
                empty
            );


            // ------------------------------------------------
            // Clear controls while safely between edges.
            // ------------------------------------------------

            wr_en = 1'b0;
            rd_en = 1'b0;
            data_in = 8'h00;

        end

    endtask


